        for line in fh:
            line=line.strip()
            if not line: continue
            try: row=json.loads(line)
            except: continue
            ts=parse_ts(row.get('timestamp'))
            if ts:
                first=first or ts; last=ts
                if prev_ts:
                    gap=(ts-prev_ts).total_seconds()
                    if gap>=60:
                        long_gaps.append((gap, prev_ts.isoformat(), ts.isoformat()))
                prev_ts=ts
            msg=row.get('message')
            if not isinstance(msg,dict): continue
            role=msg.get('role')
            if role=='user':
                c=msg.get('content')
