                    n=0
                    for b in c:
                        if isinstance(b,dict) and b.get('type')=='tool_result':
                            raw=b.get('content')
                            if isinstance(raw,str): n+=len(raw)
                            else:
                                try: n+=len(json.dumps(raw))
                                except: n+=len(str(raw))
                    tool_result_lens.append(n)
                    events.append((ts,'tool_result',n))
                else:
                    text=''
                    if isinstance(c,list):
                        for b in c:
                            if isinstance(b,dict) and b.get('type')=='text':
                                text+=str(b.get('text') or '')
                    elif isinstance(c,str): text=c
                    if text.strip() and not text.startswith('<') and len(text)>20:
                        user_prompts.append(text[:120].replace('\\n',' '))
                    events.append((ts,'user', len(text)))
            elif role=='assistant':
                asst+=1
                model=str(msg.get('model') or '')
                if model: model_votes[model]+=1
                content=msg.get('content')
                if isinstance(content,list):
                    for b in content:
                        if not isinstance(b,dict): continue
                        if b.get('type')!='tool_use': continue
                        name=b.get('name') or '?'
                        tools[name]+=1
                        inp=b.get('input') or {}
                        if name in ('Bash','bash','Shell'):
                            cmd=str(inp.get('command') or inp.get('cmd') or '')
                            bash_cmds.append((ts.isoformat() if ts else '', cmd[:300]))
                            low=cmd.lower()
                            kind=None
                            if 'npm install' in low or 'npm i ' in low or 'pnpm i' in low or 'yarn ' in low:
                                kind='npm_install'
                            elif 'pip install' in low or 'pip3 install' in low:
                                kind='pip_install'
                            elif 'cargo ' in low or 'rustup' in low:
                                kind='rust'
                            elif 'npx create' in low or 'vite' in low and 'create' in low:
