        elif low.strip().startswith('ls') or 'dir ' in low or 'pwd' in low or 'which ' in low or 'where ' in low:
            cats['explore']+=1
        elif 'mkdir' in low or 'cd ' in low: cats['fs']+=1
        else: cats['other_bash']+=1
    print('bash categories:', dict(cats))
    print(f'long gaps >=60s: {len(long_gaps)} (sum={sum(g for g,_,_ in long_gaps):.0f}s)')
    long_gaps.sort(reverse=True)
    for g,a,b in long_gaps[:12]:
        print(f'  gap {g/60:.1f}m  {a} -> {b}')
    if tool_result_lens:
        print(f'tool_result chars: n={len(tool_result_lens)} sum={sum(tool_result_lens)} max={max(tool_result_lens)} avg={sum(tool_result_lens)/len(tool_result_lens):.0f}')
    # Estimate model wait: gaps between assistant tool_use timestamp and next tool_result? hard in this format
    # Instead: gaps after user/tool_result before next assistant = model latency
    model_waits=[]
    last_userish=None
    with path.open(encoding='utf-8') as fh:
        for line in fh:
            line=line.strip()
            if not line: continue
            try: row=json.loads(line)
            except: continue
            ts=parse_ts(row.get('timestamp'))
            msg=row.get('message')
            if not isinstance(msg,dict) or not ts: continue
            role=msg.get('role')
            if role=='user':
                last_userish=ts
            elif role=='assistant' and last_userish:
                model_waits.append((ts-last_userish).total_seconds())
                last_userish=None
    if model_waits:
        model_waits_sorted=sorted(model_waits, reverse=True)
        print(f'model wait after user/tool_result: n={len(model_waits)} sum={sum(model_waits):.0f}s avg={sum(model_waits)/len(model_waits):.1f}s max={max(model_waits):.1f}s')
        print('  top waits (s):', [round(x,1) for x in model_waits_sorted[:10]])
    return runtime, installs, bash_cmds, tools

