/** Seeded room+corridor vault generator for Deepvault Survey. */

export type Pos = [number, number];

export class Dungeon {
  public map: string[][];
  public width: number;
  public height: number;
  public startPos: Pos = [1, 1];
  public shaftPos: Pos = [1, 1];
  public heartPos: Pos | null = null;
  public currentFloor = 1;
  public visible: Set<string> = new Set();
  public remembered: Set<string> = new Set();
  public items: Map<string, string> = new Map(); // "x,y" -> glyph + o *

  constructor(
    width: number,
    height: number,
    private prng: () => number,
    floor = 1
  ) {
    this.width = width;
    this.height = height;
    this.currentFloor = floor;
    this.map = Array.from({ length: height }, () =>
      Array.from({ length: width }, () => "#")
    );
    this.generate();
  }

  private randInt(lo: number, hi: number): number {
    return lo + Math.floor(this.prng() * (hi - lo + 1));
  }

  private generate() {
    type Room = { x: number; y: number; w: number; h: number; cx: number; cy: number };
    const rooms: Room[] = [];
    const attempts = 30;
    for (let i = 0; i < attempts && rooms.length < 7; i++) {
      const w = this.randInt(4, 8);
      const h = this.randInt(3, 6);
      const x = this.randInt(1, this.width - w - 2);
      const y = this.randInt(1, this.height - h - 2);
      const room = { x, y, w, h, cx: x + Math.floor(w / 2), cy: y + Math.floor(h / 2) };
      const overlaps = rooms.some(
        (r) =>
          !(
            room.x + room.w + 1 < r.x ||
            r.x + r.w + 1 < room.x ||
            room.y + room.h + 1 < r.y ||
            r.y + r.h + 1 < room.y
          )
      );
      if (overlaps) continue;
      for (let yy = y; yy < y + h; yy++) {
        for (let xx = x; xx < x + w; xx++) this.map[yy][xx] = ".";
      }
      if (rooms.length) {
        const prev = rooms[rooms.length - 1];
        this.carveL(prev.cx, prev.cy, room.cx, room.cy);
      }
      rooms.push(room);
    }
    if (!rooms.length) {
      for (let y = 1; y < this.height - 1; y++)
        for (let x = 1; x < this.width - 1; x++) this.map[y][x] = ".";
      this.startPos = [2, 2];
      this.shaftPos = [this.width - 3, this.height - 3];
    } else {
      this.startPos = [rooms[0].cx, rooms[0].cy];
      let far = rooms[0];
      let best = -1;
      for (const r of rooms) {
        const d = Math.abs(r.cx - rooms[0].cx) + Math.abs(r.cy - rooms[0].cy);
        if (d > best) {
          best = d;
          far = r;
        }
      }
      this.shaftPos = [far.cx, far.cy];
    }

    this.map[this.startPos[1]][this.startPos[0]] = ".";
    if (this.currentFloor < 3) {
      this.map[this.shaftPos[1]][this.shaftPos[0]] = ">";
      this.heartPos = null;
    } else {
      this.map[this.shaftPos[1]][this.shaftPos[0]] = "&";
      this.heartPos = [...this.shaftPos] as Pos;
    }

    // place a few items
    const itemGlyphs = ["+", "o", "*"];
    const itemCount = 2 + this.currentFloor;
    for (let i = 0; i < itemCount; i++) {
      const p = this.randomFreePosition();
      const g = itemGlyphs[this.randInt(0, 2)];
      this.items.set(`${p[0]},${p[1]}`, g);
    }
  }

  private carveL(x0: number, y0: number, x1: number, y1: number) {
    let x = x0;
    let y = y0;
    while (x !== x1) {
      this.map[y][x] = ".";
      x += x1 > x ? 1 : -1;
    }
    while (y !== y1) {
      this.map[y][x] = ".";
      y += y1 > y ? 1 : -1;
    }
    this.map[y1][x1] = ".";
  }

  public randomFreePosition(): Pos {
    for (let i = 0; i < 500; i++) {
      const x = this.randInt(1, this.width - 2);
      const y = this.randInt(1, this.height - 2);
      if (this.map[y][x] !== ".") continue;
      if (x === this.startPos[0] && y === this.startPos[1]) continue;
      if (x === this.shaftPos[0] && y === this.shaftPos[1]) continue;
      const key = `${x},${y}`;
      if (this.items.has(key)) continue;
      return [x, y];
    }
    return [this.startPos[0] + 1, this.startPos[1]];
  }

  public walkable(x: number, y: number): boolean {
    if (x < 0 || y < 0 || x >= this.width || y >= this.height) return false;
    return this.map[y][x] !== "#";
  }
}

/** Player + enemies for Deepvault Survey. */

export type Pos = [number, number];

function manhattan(a: Pos, b: Pos): number {
  return Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]);
}

export class Player {
  public pos: Pos;
  public hp = 10;
  public maxHp = 10;
  public attackDamage = 2;
  constructor(startPos: Pos) {
    this.pos = [...startPos] as Pos;
  }
}

export abstract class BaseEnemy {
  public pos: Pos;
  public hp: number;
  public dmg: number;
  public glyph: string;
  public color: string;
  constructor(pos: Pos, glyph: string, hp: number, dmg: number, color: string) {
    this.pos = [...pos] as Pos;
    this.glyph = glyph;
    this.hp = hp;
    this.dmg = dmg;
    this.color = color;
  }
  abstract takeTurn(
    player: Player,
    dungeon: { map: string[][]; width: number; height: number; walkable: (x: number, y: number) => boolean },
    prng: () => number
  ): void;
}

function tryStep(
  pos: Pos,
  dx: number,
  dy: number,
  dungeon: { walkable: (x: number, y: number) => boolean }
): Pos {
  const nx = pos[0] + dx;
  const ny = pos[1] + dy;
  if (dungeon.walkable(nx, ny)) return [nx, ny];
  return pos;
}

export class RustHusk extends BaseEnemy {
  private aware = false;
  constructor(pos: Pos, hpScale = 0) {
    super(pos, "h", 4 + hpScale, 1, "#ff8800");
  }
  takeTurn(player, dungeon, prng) {
    if (!this.aware && manhattan(this.pos, player.pos) <= 5) this.aware = true;
    if (this.aware) {
      const dx = Math.sign(player.pos[0] - this.pos[0]);
      const dy = Math.sign(player.pos[1] - this.pos[1]);
      if (dx) this.pos = tryStep(this.pos, dx, 0, dungeon);
      else if (dy) this.pos = tryStep(this.pos, 0, dy, dungeon);
    } else {
      const dirs: Pos[] = [
        [1, 0],
        [-1, 0],
        [0, 1],
        [0, -1],
      ];
      const [dx, dy] = dirs[Math.floor(prng() * 4)];
      this.pos = tryStep(this.pos, dx, dy, dungeon);
    }
    if (manhattan(this.pos, player.pos) === 0 || manhattan(this.pos, player.pos) === 1) {
      // if on same tile after move, step back conceptually — attack adjacent
    }
    if (manhattan(this.pos, player.pos) === 1) player.hp -= this.dmg;
  }
}

export class SentryCoil extends BaseEnemy {
  private charge = 0;
  public telegraphing = false;
  constructor(pos: Pos, hpScale = 0) {
    super(pos, "s", 3 + hpScale, 2, "#00aaff");
  }
  private hasLOS(player: Player, dungeon: { map: string[][] }): boolean {
    const [px, py] = player.pos;
    const [sx, sy] = this.pos;
    if (px === sx) {
      const step = py > sy ? 1 : -1;
      for (let y = sy + step; y !== py; y += step) if (dungeon.map[y][sx] === "#") return false;
      return true;
    }
    if (py === sy) {
      const step = px > sx ? 1 : -1;
      for (let x = sx + step; x !== px; x += step) if (dungeon.map[sy][x] === "#") return false;
      return true;
    }
    return false;
  }
  takeTurn(player, dungeon, _prng) {
    this.telegraphing = false;
    if (this.charge === 1) {
      if (this.hasLOS(player, dungeon)) player.hp -= this.dmg;
      this.charge = 0;
      return;
    }
    if (this.hasLOS(player, dungeon)) {
      this.charge = 1;
      this.telegraphing = true;
    }
  }
}

export class ScavRat extends BaseEnemy {
  constructor(pos: Pos, hpScale = 0) {
    super(pos, "r", 2 + hpScale, 1, "#aa5500");
  }
  takeTurn(player, dungeon, prng) {
    const dirs: Pos[] = [
      [1, 0],
      [-1, 0],
      [0, 1],
      [0, -1],
    ];
    const [dx, dy] = dirs[Math.floor(prng() * 4)];
    this.pos = tryStep(this.pos, dx, dy, dungeon);
    if (manhattan(this.pos, player.pos) === 1) player.hp -= this.dmg;
  }
}

/**
 * Deepvault Survey — playable browser core.
 */
import { Dungeon } from "./dungeon";
import {
  Player,
  RustHusk,
  SentryCoil,
  ScavRat,
  BaseEnemy,
  type Pos,
} from "./entity";
import { computeFOV } from "./fov";
import { Inventory, PatchKit, LumenFlare, SparkCharge, Item } from "./inventory";
import { UI } from "./ui";
import { snapshot, restore } from "./save";

type Mode = "menu" | "play" | "pause" | "end";

export class Game {
  canvas: HTMLCanvasElement;
  ctx: CanvasRenderingContext2D;
  tileSize = 16;
  mapWidth = 48;
  mapHeight = 28;
  seed = "";
  prngState = 0;
  prng: () => number = () => 0;

  dungeon!: Dungeon;
  player!: Player;
  entities: BaseEnemy[] = [];
  inventory = new Inventory();
  ui: UI;

  turnCount = 0;
  flareTimer = 0;
  gameOver = false;
  victory = false;
  enemiesDefeated = 0;
  itemsCollected = 0;
  stasisSnapshot: any = null;
  mode: Mode = "menu";
  seedInput = "";
  menuIndex = 0;

  constructor(canvas: HTMLCanvasElement, ctx: CanvasRenderingContext2D) {
    this.canvas = canvas;
    this.ctx = ctx;
    this.ui = new UI(canvas, ctx, this.tileSize);
    this.canvas.width = this.mapWidth * this.tileSize;
    this.canvas.height = this.mapHeight * this.tileSize + 96;
    window.addEventListener("keydown", (e) => this.handleKey(e));
    this.render();
  }

  private seedToState(seed: string): number {
    let h = 2166136261;
    for (let i = 0; i < seed.length; i++) {
      h ^= seed.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return h >>> 0;
  }

  private mulberry32(): number {
    this.prngState = (this.prngState + 0x6d2b79f5) >>> 0;
    let t = this.prngState;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  start() {
    const loop = () => {
      this.render();
      requestAnimationFrame(loop);
    };
    requestAnimationFrame(loop);
  }

  private newRun(seed?: string) {
    this.seed = (seed && seed.trim()) || Math.random().toString(36).slice(2, 8).toUpperCase();
    this.prngState = this.seedToState(this.seed);
    this.prng = () => this.mulberry32();
    this.turnCount = 0;
    this.flareTimer = 0;
    this.gameOver = false;
    this.victory = false;
    this.enemiesDefeated = 0;
    this.itemsCollected = 0;
    this.inventory = new Inventory();
    this.loadFloor(1);
    this.mode = "play";
    this.ui.log(`Expedition seed ${this.seed}. Recover the Vault Heart.`);
  }

  private loadFloor(floor: number) {
    this.dungeon = new Dungeon(this.mapWidth, this.mapHeight, this.prng, floor);
    this.player = new Player(this.dungeon.startPos);
    this.entities = [];
    const scale = floor - 1;
    const counts = [
      { n: 2 + floor, make: (p: Pos) => new RustHusk(p, scale) },
      { n: 1 + Math.floor(floor / 2), make: (p: Pos) => new SentryCoil(p, scale) },
      { n: 2 + floor, make: (p: Pos) => new ScavRat(p, scale) },
    ];
    for (const c of counts) {
      for (let i = 0; i < c.n; i++) {
        const pos = this.dungeon.randomFreePosition();
        this.entities.push(c.make(pos));
      }
    }
    this.updateFOV();
  }

  handleKey(e: KeyboardEvent) {
    if (this.mode === "menu") {
      if (e.key === "ArrowUp" || e.key === "w") this.menuIndex = (this.menuIndex + 2) % 3;
      if (e.key === "ArrowDown" || e.key === "s") this.menuIndex = (this.menuIndex + 1) % 3;
      if (/^[a-zA-Z0-9]$/.test(e.key) && this.menuIndex === 0) {
        if (this.seedInput.length < 12) this.seedInput += e.key.toUpperCase();
      }
      if (e.key === "Backspace" && this.menuIndex === 0) this.seedInput = this.seedInput.slice(0, -1);
      if (e.key === "Enter") {
        if (this.menuIndex === 0) this.newRun(this.seedInput || undefined);
        else if (this.menuIndex === 1) {
          if (this.stasisSnapshot) {
            restore(this, this.stasisSnapshot);
            this.mode = "play";
            this.ui.log("Stasis restored.");
          } else this.ui.log("No stasis snapshot in this tab.");
        } else {
          this.ui.log("WASD/Arrows move · bump attack · 1-3 items · F5 stasis · F9 resume · Esc pause");
        }
      }
      return;
    }

    if (this.mode === "end") {
      if (e.key === "Enter" || e.key === " ") {
        this.mode = "menu";
        this.seedInput = "";
      }
      return;
    }

    if (this.mode === "pause") {
      if (e.key === "Escape" || e.key === "p" || e.key === "P") this.mode = "play";
      if (e.key === "F5") {
        this.stasisSnapshot = snapshot(this);
        this.ui.log("Stasis save captured (memory only — lost on refresh).");
      }
      if (e.key === "F9" && this.stasisSnapshot) {
        restore(this, this.stasisSnapshot);
        this.mode = "play";
        this.ui.log("Stasis restored.");
      }
      return;
    }

    if (this.mode !== "play" || this.gameOver) return;

    if (e.key === "Escape" || e.key === "p" || e.key === "P") {
      this.mode = "pause";
      return;
    }
    if (e.key === "F5") {
      e.preventDefault();
      this.stasisSnapshot = snapshot(this);
      this.ui.log("Stasis save captured (tab memory only).");
      return;
    }
    if (e.key === "F9") {
      e.preventDefault();
      if (this.stasisSnapshot) {
        restore(this, this.stasisSnapshot);
        this.ui.log("Stasis restored.");
      } else this.ui.log("No stasis yet.");
      return;
    }
    if (e.key === "1") {
      this.inventory.use(0, this);
      return;
    }
    if (e.key === "2") {
      this.inventory.use(1, this);
      return;
    }
    if (e.key === "3") {
      this.inventory.use(2, this);
      return;
    }

    let dx = 0;
    let dy = 0;
    const k = e.key.toLowerCase();
    if (k === "arrowup" || k === "w" || k === "k") dy = -1;
    else if (k === "arrowdown" || k === "s" || k === "j") dy = 1;
    else if (k === "arrowleft" || k === "a" || k === "h") dx = -1;
    else if (k === "arrowright" || k === "d" || k === "l") dx = 1;
    else if (k === "y") {
      dx = -1;
      dy = -1;
    } else if (k === "u") {
      dx = 1;
      dy = -1;
    } else if (k === "b") {
      dx = -1;
      dy = 1;
    } else if (k === "n") {
      dx = 1;
      dy = 1;
    } else return;

    e.preventDefault();
    this.playerAct(dx, dy);
  }

  private playerAct(dx: number, dy: number) {
    const nx = this.player.pos[0] + dx;
    const ny = this.player.pos[1] + dy;
    if (!this.dungeon.walkable(nx, ny)) return;

    const enemy = this.entities.find((en) => en.pos[0] === nx && en.pos[1] === ny);
    if (enemy) {
      enemy.hp -= this.player.attackDamage;
      this.ui.log(`You strike ${enemy.glyph} (${enemy.hp} hp).`);
      if (enemy.hp <= 0) {
        this.entities = this.entities.filter((e) => e !== enemy);
        this.enemiesDefeated++;
        this.ui.log(`${enemy.glyph} falls apart.`);
      }
    } else {
      this.player.pos = [nx, ny];
      this.pickup();
      const tile = this.dungeon.map[ny][nx];
      if (tile === ">" && this.dungeon.currentFloor < 3) {
        this.ui.log(`Descending to vault depth ${this.dungeon.currentFloor + 1}...`);
        this.loadFloor(this.dungeon.currentFloor + 1);
        this.turnCount++;
        this.enemiesAct();
        this.tickStatus();
        this.updateFOV();
        this.checkEnd();
        return;
      }
      if (tile === "&") {
        this.victory = true;
        this.gameOver = true;
        this.mode = "end";
        this.ui.log("Vault Heart recovered!");
        return;
      }
    }

    this.turnCount++;
    this.enemiesAct();
    this.tickStatus();
    this.updateFOV();
    this.checkEnd();
  }

  private pickup() {
    const key = `${this.player.pos[0]},${this.player.pos[1]}`;
    const g = this.dungeon.items.get(key);
    if (!g) return;
    let item: Item | null = null;
    if (g === "+") item = new PatchKit();
    else if (g === "o") item = new LumenFlare();
    else if (g === "*") item = new SparkCharge();
    if (!item) return;
    if (this.inventory.add(item)) {
      this.dungeon.items.delete(key);
      this.itemsCollected++;
      this.ui.log(`Salvaged ${item.name}.`);
    } else {
      this.ui.log("Inventory full — leave the salvage.");
    }
  }

  private enemiesAct() {
    for (const e of [...this.entities]) {
      if (e.hp <= 0) continue;
      // don't walk onto other enemies / player tile for movement simplicity
      const before = [...e.pos] as Pos;
      e.takeTurn(this.player, this.dungeon, this.prng);
      // prevent stacking on player by attack-only if moved onto player
      if (e.pos[0] === this.player.pos[0] && e.pos[1] === this.player.pos[1]) {
        e.pos = before;
        this.player.hp -= e.dmg;
        this.ui.log(`${e.glyph} hits you!`);
      }
      // scav rats eat items
      if (e instanceof ScavRat) {
        const k = `${e.pos[0]},${e.pos[1]}`;
        if (this.dungeon.items.has(k)) {
          this.dungeon.items.delete(k);
          this.ui.log("Scav Rat consumes a salvage!");
        }
      }
    }
  }

  private tickStatus() {
    if (this.flareTimer > 0) this.flareTimer--;
  }

  private updateFOV() {
    const radius = this.flareTimer > 0 ? 12 : 6;
    const vis = computeFOV(this.dungeon.map, this.player.pos, radius);
    this.dungeon.visible = vis;
    for (const k of vis) this.dungeon.remembered.add(k);
  }

  private checkEnd() {
    if (this.player.hp <= 0) {
      this.player.hp = 0;
      this.victory = false;
      this.gameOver = true;
      this.mode = "end";
      this.ui.log("Signal Lost.");
    }
  }

  calculateScore(): number {
    return Math.max(
      0,
      25 * this.enemiesDefeated +
        15 * this.itemsCollected +
        100 * this.dungeon.currentFloor -
        this.turnCount
    );
  }

  private render() {
    const ctx = this.ctx;
    ctx.fillStyle = "#05080c";
    ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);

    if (this.mode === "menu") {
      ctx.fillStyle = "#7dffb3";
      ctx.font = "22px monospace";
      ctx.fillText("DEEPVAULT SURVEY", 40, 60);
      ctx.fillStyle = "#9ab";
      ctx.font = "14px monospace";
      ctx.fillText("Recover the Vault Heart across 3 flooded data floors.", 40, 90);
      const opts = [
        `New Expedition  seed:[${this.seedInput || "auto"}]`,
        `Resume Stasis${this.stasisSnapshot ? "" : " (empty)"}`,
        "How to Play",
      ];
      opts.forEach((o, i) => {
        ctx.fillStyle = i === this.menuIndex ? "#fff" : "#678";
        ctx.fillText(`${i === this.menuIndex ? ">" : " "} ${o}`, 40, 140 + i * 28);
      });
      ctx.fillStyle = "#567";
      ctx.fillText("Up/Down select · type seed · Enter confirm", 40, 260);
      this.ui.renderHUD(this);
      return;
    }

    if (this.mode === "end") {
      ctx.fillStyle = this.victory ? "#7dffb3" : "#f66";
      ctx.font = "24px monospace";
      ctx.fillText(this.victory ? "VAULT HEART SECURED" : "SIGNAL LOST", 40, 80);
      ctx.fillStyle = "#ccc";
      ctx.font = "16px monospace";
      ctx.fillText(`Salvage score: ${this.calculateScore()}`, 40, 120);
      ctx.fillText(`Seed: ${this.seed}`, 40, 150);
      ctx.fillText(`Turns: ${this.turnCount}  Depth: ${this.dungeon.currentFloor}/3`, 40, 180);
      ctx.fillText("Enter — return to menu", 40, 230);
      return;
    }

    // play / pause map
    for (let y = 0; y < this.dungeon.height; y++) {
      for (let x = 0; x < this.dungeon.width; x++) {
        const key = `${x},${y}`;
        const visible = this.dungeon.visible.has(key);
        const remembered = this.dungeon.remembered.has(key);
        if (!visible && !remembered) continue;
        let glyph = this.dungeon.map[y][x];
        const item = this.dungeon.items.get(key);
        if (item && (visible || remembered)) glyph = item;
        ctx.fillStyle = visible ? "#cde" : "#445";
        if (glyph === "#") ctx.fillStyle = visible ? "#6a8" : "#234";
        if (glyph === ">") ctx.fillStyle = visible ? "#ffcc66" : "#664";
        if (glyph === "&") ctx.fillStyle = visible ? "#ff66cc" : "#623";
        if (item) ctx.fillStyle = visible ? "#ff0" : "#660";
        ctx.font = `${this.tileSize}px monospace`;
        ctx.fillText(glyph, x * this.tileSize, (y + 1) * this.tileSize);
      }
    }

    for (const e of this.entities) {
      const key = `${e.pos[0]},${e.pos[1]}`;
      if (!this.dungeon.visible.has(key)) continue;
      ctx.fillStyle =
        e instanceof SentryCoil && (e as SentryCoil).telegraphing ? "#fff" : e.color;
      ctx.fillText(e.glyph, e.pos[0] * this.tileSize, (e.pos[1] + 1) * this.tileSize);
    }

    ctx.fillStyle = "#7dffb3";
    ctx.fillText("@", this.player.pos[0] * this.tileSize, (this.player.pos[1] + 1) * this.tileSize);

    this.ui.renderHUD(this);

    if (this.mode === "pause") {
      ctx.fillStyle = "rgba(0,0,0,0.65)";
      ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);
      ctx.fillStyle = "#fff";
      ctx.font = "20px monospace";
      ctx.fillText("PAUSED — Esc continue · F5 Stasis · F9 Resume", 40, 80);
    }
  }
}

import type { Game } from "./game";
import { RustHusk, SentryCoil, ScavRat } from "./entity";
import { PatchKit, LumenFlare, SparkCharge } from "./inventory";

export function snapshot(game: Game): any {
  return JSON.parse(
    JSON.stringify({
      seed: game.seed,
      prngState: game.prngState,
      turnCount: game.turnCount,
      flareTimer: game.flareTimer,
      enemiesDefeated: game.enemiesDefeated,
      itemsCollected: game.itemsCollected,
      player: {
        pos: [...game.player.pos],
        hp: game.player.hp,
        maxHp: game.player.maxHp,
        attackDamage: game.player.attackDamage,
      },
      dungeon: {
        map: game.dungeon.map.map((row) => [...row]),
        width: game.dungeon.width,
        height: game.dungeon.height,
        startPos: [...game.dungeon.startPos],
        shaftPos: [...game.dungeon.shaftPos],
        currentFloor: game.dungeon.currentFloor,
        visible: Array.from(game.dungeon.visible),
        remembered: Array.from(game.dungeon.remembered),
        items: Array.from(game.dungeon.items.entries()),
      },
      entities: game.entities.map((e) => ({
        glyph: e.glyph,
        hp: e.hp,
        dmg: e.dmg,
        pos: [...e.pos],
        type: e.constructor.name,
        telegraphing: (e as any).telegraphing || false,
        charge: (e as any).charge || 0,
        aware: (e as any).aware || false,
      })),
      inventory: {
        slots: game.inventory.slots.map((it) => (it ? { type: it.constructor.name } : null)),
      },
      gameOver: game.gameOver,
      victory: game.victory,
    })
  );
}

export function restore(game: Game, state: any) {
  game.seed = state.seed;
  game.prngState = state.prngState;
  game.prng = () => {
    game.prngState = (game.prngState + 0x6d2b79f5) >>> 0;
    let t = game.prngState;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  game.turnCount = state.turnCount;
  game.flareTimer = state.flareTimer;
  game.enemiesDefeated = state.enemiesDefeated || 0;
  game.itemsCollected = state.itemsCollected || 0;
  game.player.pos = [...state.player.pos];
  game.player.hp = state.player.hp;
  game.player.maxHp = state.player.maxHp;
  game.player.attackDamage = state.player.attackDamage;
  game.dungeon.map = state.dungeon.map.map((row: string[]) => [...row]);
  game.dungeon.width = state.dungeon.width;
  game.dungeon.height = state.dungeon.height;
  game.dungeon.startPos = [...state.dungeon.startPos];
  game.dungeon.shaftPos = [...state.dungeon.shaftPos];
  game.dungeon.currentFloor = state.dungeon.currentFloor;
  game.dungeon.visible = new Set(state.dungeon.visible);
  game.dungeon.remembered = new Set(state.dungeon.remembered);
  game.dungeon.items = new Map(state.dungeon.items || []);
  const typeMap: Record<string, any> = { RustHusk, SentryCoil, ScavRat };
  game.entities = state.entities.map((e: any) => {
    const ctor = typeMap[e.type] || RustHusk;
    const inst = new ctor(e.pos);
    inst.hp = e.hp;
    inst.dmg = e.dmg;
    if ("aware" in inst) (inst as any).aware = e.aware;
    if ("charge" in inst) (inst as any).charge = e.charge;
    if ("telegraphing" in inst) (inst as any).telegraphing = e.telegraphing;
    return inst;
  });
  const itemMap: Record<string, any> = { PatchKit, LumenFlare, SparkCharge };
  game.inventory.slots = state.inventory.slots.map((s: any) =>
    s ? new itemMap[s.type]() : null
  );
  game.gameOver = state.gameOver;
  game.victory = state.victory;
  game.mode = "play";
}

import type { Game } from "./game";

export abstract class Item {
  abstract name: string;
  abstract glyph: string;
  abstract use(game: Game): void;
}

export class PatchKit extends Item {
  name = "Patch Kit";
  glyph = "+";
  use(game: Game) {
    const heal = 6;
    game.player.hp = Math.min(game.player.maxHp, game.player.hp + heal);
    game.ui.log(`Patched +${heal} HP.`);
  }
}

export class LumenFlare extends Item {
  name = "Lumen Flare";
  glyph = "o";
  use(game: Game) {
    game.flareTimer = 6;
    game.ui.log("Lumen flare — vision expanded.");
  }
}

export class SparkCharge extends Item {
  name = "Spark Charge";
  glyph = "*";
  use(game: Game) {
    const [px, py] = game.player.pos;
    let hit = false;
    for (let i = game.entities.length - 1; i >= 0; i--) {
      const e = game.entities[i];
      if (Math.abs(e.pos[0] - px) <= 2 && Math.abs(e.pos[1] - py) <= 2) {
        e.hp -= 4;
        hit = true;
        if (e.hp <= 0) {
          game.entities.splice(i, 1);
          game.enemiesDefeated++;
          game.ui.log(`${e.glyph} destroyed by spark.`);
        }
      }
    }
    if (!hit) game.ui.log("Spark wasted — no husks in range.");
  }
}

export class Inventory {
  slots: (Item | null)[] = [null, null, null];
  add(item: Item): boolean {
    for (let i = 0; i < this.slots.length; i++) {
      if (!this.slots[i]) {
        this.slots[i] = item;
        return true;
      }
    }
    return false;
  }
  use(slotIdx: number, game: Game): void {
    const item = this.slots[slotIdx];
    if (!item) {
      game.ui.log("Empty slot.");
      return;
    }
    item.use(game);
    this.slots[slotIdx] = null;
  }
}

import type { Game } from "./game";

export class UI {
  private ctx: CanvasRenderingContext2D;
  private tileSize: number;
  private logLines: string[] = [];
  private maxLog = 4;

  constructor(
    _canvas: HTMLCanvasElement,
    ctx: CanvasRenderingContext2D,
    tileSize: number
  ) {
    this.ctx = ctx;
    this.tileSize = tileSize;
  }

  logMessage(msg: string) {
    this.logLines.push(msg);
    if (this.logLines.length > this.maxLog) this.logLines.shift();
  }

  log(msg: string) {
    this.logMessage(msg);
  }

  renderHUD(game: Game) {
    const ctx = this.ctx;
    const yBase = game.mapHeight * this.tileSize + 14;
    ctx.fillStyle = "#9ab";
    ctx.font = "13px monospace";
    if (!game.player) {
      for (let i = 0; i < this.logLines.length; i++) {
        ctx.fillText(this.logLines[this.logLines.length - 1 - i], 8, yBase + 20 + i * 16);
      }
      return;
    }
    ctx.fillStyle = "#cde";
    ctx.fillText(
      `HP ${game.player.hp}/${game.player.maxHp}   D${game.dungeon.currentFloor}/3   Seed ${game.seed}   Turns ${game.turnCount}`,
      8,
      yBase
    );
    if (game.flareTimer > 0) {
      ctx.fillStyle = "#ffcc66";
      ctx.fillText(`Flare ${game.flareTimer}`, 520, yBase);
    }
    for (let i = 0; i < game.inventory.slots.length; i++) {
      const slotX = 8 + i * 70;
      ctx.strokeStyle = "#567";
      ctx.strokeRect(slotX, yBase + 8, 60, 22);
      const item = game.inventory.slots[i];
      ctx.fillStyle = "#ff0";
      ctx.fillText(
        `${i + 1}:${item ? item.glyph + " " + item.name.slice(0, 6) : "-"}`,
        slotX + 4,
        yBase + 24
      );
    }
    ctx.fillStyle = "#8ab";
    for (let i = 0; i < this.logLines.length; i++) {
      const line = this.logLines[this.logLines.length - 1 - i];
      ctx.fillText(line, 230, yBase + 24 + i * 14);
    }
  }
}

