/**
 * Keep Langfuse payloads small so flush finishes inside Cursor hook timeouts.
 */

export const MAX_STRING_CHARS = 24_000;
export const MAX_JSON_CHARS = 48_000;

export function truncateString(value, max = MAX_STRING_CHARS) {
  if (value == null) return value;
  const text = typeof value === "string" ? value : String(value);
  if (text.length <= max) return text;
  return `${text.slice(0, max)}\n…[truncated ${text.length - max} chars]`;
}

export function truncateJson(value, max = MAX_JSON_CHARS) {
  if (value == null) return value;
  if (typeof value === "string") return truncateString(value, max);

  try {
    const serialized = JSON.stringify(value);
    if (serialized.length <= max) return value;
    return {
      truncated: true,
      preview: serialized.slice(0, Math.min(max, 8_000)),
      original_length: serialized.length,
    };
  } catch {
    return { truncated: true, reason: "unserializable" };
  }
}

/**
 * Langfuse Client Module
 *
 * Data model (https://langfuse.com/faq/all/what-does-a-good-trace-look-like):
 * - Session  = one Cursor chat (conversation_id)
 * - Trace    = one agent turn (generation_id): user prompt → agent response
 * - Tools    = child observations on the trace
 * - Generation = LLM output only (agent response)
 */

import { Langfuse } from "langfuse";
import { config } from "dotenv";
import { resolve, dirname, join } from "path";
import { fileURLToPath } from "url";
import { appendFileSync, mkdirSync, existsSync } from "fs";
import { generateTraceName, generateSessionId, generateTraceTags } from "./utils.js";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const hooksRoot = resolve(__dirname, "..");
const logDir = join(hooksRoot, "logs");
const logFile = join(logDir, "langfuse-hooks.log");

function loadEnv() {
  const envCandidates = [
    resolve(hooksRoot, ".env", "Credentials.txt"),
    resolve(hooksRoot, ".env"),
    resolve(process.cwd(), ".env", "Credentials.txt"),
    resolve(process.cwd(), ".env"),
  ];

  for (const envPath of envCandidates) {
    config({ path: envPath });
    if (process.env.LANGFUSE_SECRET_KEY) break;
  }

  // Normalize values from Credentials.txt (trim + strip trailing slash on URL)
  for (const key of [
    "LANGFUSE_SECRET_KEY",
    "LANGFUSE_PUBLIC_KEY",
    "LANGFUSE_BASE_URL",
    "LANGFUSE_ENVIRONMENT",
  ]) {
    if (typeof process.env[key] === "string") {
      process.env[key] = process.env[key].trim();
    }
  }
  if (process.env.LANGFUSE_BASE_URL) {
    process.env.LANGFUSE_BASE_URL = process.env.LANGFUSE_BASE_URL.replace(/\/+$/, "");
  }
}

loadEnv();

export const HOOK_HANDLER_VERSION = "1.4.0";

/** Hooks that only return allow/continue and must not open a Langfuse network round-trip. */
export const NO_TRACE_HOOKS = new Set([
  "beforeShellExecution",
  "beforeMCPExecution",
  "preToolUse",
]);

let langfuseInstance = null;
let initError = null;

export function hookLog(message, extra = null) {
  try {
    if (!existsSync(logDir)) mkdirSync(logDir, { recursive: true });
    const line =
      `[${new Date().toISOString()}] ${message}` +
      (extra != null ? ` ${typeof extra === "string" ? extra : JSON.stringify(extra)}` : "") +
      "\n";
    appendFileSync(logFile, line);
  } catch {
    // never break the agent for logging
  }
  console.error(`[Langfuse Hook v${HOOK_HANDLER_VERSION}] ${message}`);
}

function assertConfigured() {
  if (!process.env.LANGFUSE_SECRET_KEY || !process.env.LANGFUSE_PUBLIC_KEY) {
    throw new Error(
      "Missing LANGFUSE_SECRET_KEY / LANGFUSE_PUBLIC_KEY (expected hooks/.env/Credentials.txt)"
    );
  }
}

export function getLangfuseClient() {
  if (initError) throw initError;
  if (!langfuseInstance) {
    try {
      assertConfigured();
      langfuseInstance = new Langfuse({
        secretKey: process.env.LANGFUSE_SECRET_KEY,
        publicKey: process.env.LANGFUSE_PUBLIC_KEY,
        baseUrl: process.env.LANGFUSE_BASE_URL || "https://cloud.langfuse.com",
        release: HOOK_HANDLER_VERSION,
        environment: process.env.LANGFUSE_ENVIRONMENT || "development",
        // Flush every event; hooks are short-lived processes.
        flushAt: 1,
        requestTimeout: 20_000,
      });
    } catch (err) {
      initError = err;
      hookLog(`init failed: ${err.message}`);
      throw err;
    }
  }
  return langfuseInstance;
}

export function testLangfuseClientConfig() {
  return {
    version: HOOK_HANDLER_VERSION,
    hasSecretKey: Boolean(process.env.LANGFUSE_SECRET_KEY),
    hasPublicKey: Boolean(process.env.LANGFUSE_PUBLIC_KEY),
    baseUrl: process.env.LANGFUSE_BASE_URL || "https://cloud.langfuse.com",
    environment: process.env.LANGFUSE_ENVIRONMENT || "development",
  };
}

/**
 * Stable Langfuse trace id for one agent turn.
 * Falls back when Cursor omits generation_id (session / tab / some shell events).
 */
export function resolveTraceId(input) {
  if (input.generation_id) return String(input.generation_id);

  const conversationId = input.conversation_id || input.session_id;
  if (conversationId && input.hook_event_name?.startsWith("session")) {
    return `cursor-session-${conversationId}`;
  }
  if (conversationId) {
    return `cursor-chat-${conversationId}-nogeneration`;
  }
  return `cursor-orphan-${Date.now()}`;
}

/**
 * Get or create the trace for the current agent turn.
 * Trace ID = generation_id (one turn). Session ID = conversation_id (whole chat).
 */
export function getOrCreateTrace(input) {
  const langfuse = getLangfuseClient();
  const traceId = resolveTraceId(input);
  const sessionId = generateSessionId(input.conversation_id || input.session_id);

  const body = {
    id: traceId,
    sessionId,
    userId: input.user_email || undefined,
    release: HOOK_HANDLER_VERSION,
    version: input.cursor_version,
    metadata: {
      conversation_id: input.conversation_id || input.session_id,
      generation_id: input.generation_id || null,
      cursor_version: input.cursor_version,
      model: input.model,
      workspace_roots: input.workspace_roots,
      hook_event: input.hook_event_name,
      hook_handler_version: HOOK_HANDLER_VERSION,
    },
    tags: generateTraceTags(input),
  };

  // Only set name on first touch (beforeSubmitPrompt) to avoid overwriting on later hooks.
  if (input.prompt) {
    body.name = generateTraceName(input.prompt, input.model);
  } else if (input.hook_event_name === "sessionStart") {
    body.name = `Cursor session ${String(input.conversation_id || input.session_id || "").slice(0, 8)}`;
  }

  return langfuse.trace(body);
}

export function addScore(trace, name, value, comment = null, dataType = "NUMERIC") {
  if (trace) {
    trace.score({ name, value, comment, dataType });
  }
}

export function addCompletionScores(trace, input) {
  let statusScore = 0;
  let statusComment = "";

  switch (input.status) {
    case "completed":
      statusScore = 1;
      statusComment = "Agent completed successfully";
      break;
    case "aborted":
      statusScore = 0.5;
      statusComment = "Agent was aborted by user";
      break;
    case "error":
      statusScore = 0;
      statusComment = "Agent encountered an error";
      break;
    default:
      statusScore = 0.5;
      statusComment = `Unknown status: ${input.status}`;
  }

  addScore(trace, "completion_status", statusScore, statusComment);

  if (typeof input.loop_count === "number") {
    const efficiencyScore = Math.max(0, 1 - input.loop_count / 10);
    addScore(
      trace,
      "efficiency",
      efficiencyScore,
      `Completed in ${input.loop_count} loops`
    );
  }
}

export async function flushLangfuse() {
  const started = Date.now();
  try {
    await getLangfuseClient().flushAsync();
    hookLog(`flush ok ${Date.now() - started}ms`);
  } catch (err) {
    hookLog(`flush failed after ${Date.now() - started}ms: ${err.message}`);
    throw err;
  }
}

export async function shutdownLangfuse() {
  await getLangfuseClient().shutdownAsync();
}

#!/usr/bin/env node

/**
 * Cursor Hooks Langfuse Integration
 *
 * Langfuse data model:
 * - Session  = conversation_id (one Cursor chat, multi-turn)
 * - Trace    = generation_id (one agent turn: prompt → response)
 * - Tools    = one observation per tool call, action-named
 * - Generation = agent-response only (LLM output)
 *
 * @see https://langfuse.com/faq/all/what-does-a-good-trace-look-like
 * @see https://cursor.com/docs/agent/hooks
 */

import { readStdin } from "./lib/utils.js";
import {
  getOrCreateTrace,
  flushLangfuse,
  HOOK_HANDLER_VERSION,
  NO_TRACE_HOOKS,
  hookLog,
  testLangfuseClientConfig,
} from "./lib/langfuse-client.js";
import { routeHookHandler } from "./lib/handlers.js";

function safeAllow() {
  console.log(JSON.stringify({ continue: true, permission: "allow" }));
}

async function main() {
  try {
    const input = await readStdin();
    const hookName = input.hook_event_name || "unknown";

    // Permission-only hooks: return immediately without Langfuse network I/O.
    // Command/chat recording happens on after* / beforeSubmitPrompt / stop / etc.
    if (NO_TRACE_HOOKS.has(hookName)) {
      const response = routeHookHandler(hookName, null, input);
      console.log(JSON.stringify(response ?? { permission: "allow" }));
      return;
    }

    const cfg = testLangfuseClientConfig();
    if (!cfg.hasSecretKey || !cfg.hasPublicKey) {
      hookLog("missing credentials — allowing without ingest", {
        hook: hookName,
        baseUrl: cfg.baseUrl,
      });
      const response = routeHookHandler(hookName, null, input);
      if (response !== null && response !== undefined) {
        console.log(JSON.stringify(response));
      } else {
        safeAllow();
      }
      return;
    }

    const trace = getOrCreateTrace(input);
    const response = routeHookHandler(hookName, trace, input);

    if (response !== null && response !== undefined) {
      console.log(JSON.stringify(response));
    }

    await flushLangfuse();
    hookLog("ingested", {
      hook: hookName,
      conversation_id: input.conversation_id || input.session_id || null,
      generation_id: input.generation_id || null,
    });
  } catch (error) {
    hookLog(`Error: ${error.message}`);
    safeAllow();
    // Exit 0 so Cursor keeps fail-open behavior without treating hooks as broken.
    process.exit(0);
  }
}

