    instr = next(i for i in instruments_for_seed(seed) if i["symbol"] == symbol)
    rng = SplitMix64(seed + hash_symbol(symbol))
    log_p = math.log(float(instr["base"]))
    events = set(event_ticks(seed))
    for t in range(tick + 1):
        u1 = max(1e-12, rng.float64())
        u2 = rng.float64()
        z = math.sqrt(-2.0 * math.log(u1)) * math.cos(2 * math.pi * u2)
        log_p += instr["drift"] + instr["vol"] * z
        if t in events and instr["sector"] == SECTORS[hash_symbol(symbol) % len(SECTORS)]:
            log_p += (rng.float64() - 0.5) * 0.08
        # simpler: shock any instrument whose sector matches event target
        if t in events:
            # each event targets one sector deterministically
            pass
    # Apply sector shocks: event i targets sector i % 5
    for idx, et in enumerate(event_ticks(seed)):
        if tick >= et and instr["sector"] == SECTORS[idx % len(SECTORS)]:
            shock_rng = SplitMix64(seed + 999 + et)
            log_p += (shock_rng.float64() - 0.5) * 0.12
