export interface SkillCriterion {
  skill: string;
  synonyms: string[];
  weight: number;
}

export interface RoleProfile {
  id: string;
  name: string;
  jobDescription?: string;
  criteria: SkillCriterion[];
  sectionWeights?: { [section: string]: number };
  thresholds: { advance: number; hold: number };
}

export interface ResumeAsset {
  id: string;
  filename: string;
  rawText: string;
  importedAt: string;
  status: 'valid' | 'invalid' | 'error';
  errorReason?: string;
}

export interface CriterionResult {
  criterion: string;
  matched: boolean;
  evidenceSpans: { start: number; end: number }[];
  points: number;
}

export interface ScreeningResult {
  resumeId: string;
  profileId: string;
  totalScore: number;
  breakdown: CriterionResult[];
  confidence: number;
  matchedSkills: string[];
  missingSkills: string[];
  explanation?: string;
}

export type Bucket = 'advance' | 'hold' | 'reject';

export interface ReviewDecision {
  resumeId: string;
  bucket: Bucket;
  decidedBy: string;
  timestamp: string;
  note?: string;
  confirmed: boolean;
}

export interface AuditEvent {
  type: string;
  payload: Record<string, unknown>;
  timestamp: string;
}

export interface Workspace {
  version: 1;
  profiles: RoleProfile[];
  activeProfileId: string;
  resumes: ResumeAsset[];
  results: ScreeningResult[];
  decisions: ReviewDecision[];
  audit: AuditEvent[];
}

export type ViewId = 'queue' | 'detail' | 'roles';

import type { RoleProfile, ResumeAsset, ScreeningResult, CriterionResult, Bucket } from './types';

const MAX_BYTES = 200 * 1024;

export function validateResumeText(
  filename: string,
  rawText: string
): { ok: true } | { ok: false; reason: string } {
  const lower = filename.toLowerCase();
  if (!lower.endsWith('.txt') && !lower.endsWith('.md')) {
    return { ok: false, reason: `Unsupported file type for "${filename}" (only .txt / .md).` };
  }
  if (!rawText || !rawText.trim()) {
    return { ok: false, reason: `Empty file rejected: "${filename}".` };
  }
  const bytes = new TextEncoder().encode(rawText).length;
  if (bytes > MAX_BYTES) {
    return { ok: false, reason: `File too large (>200 KB): "${filename}".` };
  }
  return { ok: true };
}

/**
 * Deterministic rubric scorer — keyword + synonym match with evidence spans.
 */
export function scoreResume(resume: ResumeAsset, profile: RoleProfile): ScreeningResult {
  const text = resume.rawText ?? '';
  const lower = text.toLowerCase();
  const breakdown: CriterionResult[] = [];
  let totalPoints = 0;
  let maxPoints = 0;
  const matchedSkills: string[] = [];
  const missingSkills: string[] = [];

  for (const crit of profile.criteria) {
    const terms = [crit.skill, ...(crit.synonyms ?? [])]
      .map((t) => t.toLowerCase())
      .filter(Boolean);
    let found = false;
    const spans: { start: number; end: number }[] = [];
    for (const term of terms) {
      const idx = lower.indexOf(term);
      if (idx !== -1) {
        found = true;
        spans.push({ start: idx, end: idx + term.length });
        break;
      }
    }
    const points = found ? crit.weight : 0;
    totalPoints += points;
    maxPoints += crit.weight;
    breakdown.push({
      criterion: crit.skill,
      matched: found,
      evidenceSpans: spans,
      points,
    });
    if (found) matchedSkills.push(crit.skill);
    else missingSkills.push(crit.skill);
  }

  const totalScore = maxPoints ? Math.round((totalPoints / maxPoints) * 1000) / 10 : 0;
  const confidence = maxPoints ? Math.round((matchedSkills.length / profile.criteria.length) * 100) / 100 : 0;

  return {
    resumeId: resume.id,
    profileId: profile.id,
    totalScore,
    breakdown,
    confidence,
    matchedSkills,
    missingSkills,
    explanation:
      matchedSkills.length === 0
        ? 'no criteria matched — score 0; resume lacks rubric keywords/synonyms'
        : undefined,
  };
}

export function suggestedBucket(score: number, thresholds: RoleProfile['thresholds']): Bucket {
  if (score >= thresholds.advance) return 'advance';
  if (score >= thresholds.hold) return 'hold';
  return 'reject';
}

export const THRESHOLD_PRESETS = {
  strict: { advance: 80, hold: 55 },
  'open-cohort': { advance: 60, hold: 30 },
} as const;

import type { Workspace, AuditEvent } from './types';
import { createSeedWorkspace } from './seed';

const KEY = 'meritlens.v1';

export function loadWorkspace(): Workspace {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return createSeedWorkspace();
    const parsed = JSON.parse(raw) as Workspace;
    if (!parsed || parsed.version !== 1 || !Array.isArray(parsed.profiles)) {
      console.warn('MeritLens: corrupt workspace — resetting to seed');
      const seed = createSeedWorkspace();
      saveWorkspace(seed);
      return seed;
    }
    return parsed;
  } catch {
    console.warn('MeritLens: failed to parse workspace — resetting');
    const seed = createSeedWorkspace();
    try {
      saveWorkspace(seed);
    } catch {
      /* quota */
    }
    return seed;
  }
}

export function saveWorkspace(ws: Workspace): string | null {
  try {
    localStorage.setItem(KEY, JSON.stringify(ws));
    return null;
  } catch (e) {
    const msg = e instanceof Error ? e.message : 'localStorage write failed';
    return `Storage error (quota?): ${msg}`;
  }
}

export function audit(ws: Workspace, type: string, payload: Record<string, unknown>): AuditEvent {
  const ev: AuditEvent = { type, payload, timestamp: new Date().toISOString() };
  ws.audit.push(ev);
  return ev;
}

export function exportWorkspaceJson(ws: Workspace): string {
  return JSON.stringify(ws, null, 2);
}

export function exportDecisionsCsv(ws: Workspace): string {
  const header = 'resumeId,filename,bucket,score,confirmed,decidedBy,timestamp,note';
  const rows = ws.decisions.map((d) => {
    const resume = ws.resumes.find((r) => r.id === d.resumeId);
    const result = ws.results.find((r) => r.resumeId === d.resumeId);
    const cells = [
      d.resumeId,
      resume?.filename ?? '',
      d.bucket,
      result?.totalScore ?? '',
      d.confirmed,
      d.decidedBy,
      d.timestamp,
      (d.note ?? '').replace(/,/g, ';'),
    ];
    return cells.join(',');
  });
  return [header, ...rows].join('\n');
}

export function importWorkspaceJson(text: string): Workspace | { error: string } {
  try {
    const parsed = JSON.parse(text) as Workspace;
    if (!parsed || parsed.version !== 1) return { error: 'Invalid workspace JSON (need version:1)' };
    return parsed;
  } catch {
    return { error: 'Could not parse workspace JSON' };
  }
}

import type { Workspace, RoleProfile, ResumeAsset } from './types';
import { scoreResume, suggestedBucket } from './engine';

const RIVERA = `Jordan Rivera
Journeyman track applicant — Industrial Maintenance

CERTIFICATIONS
- OSHA-30 Construction completed 2023
- NCCER Core Curriculum + Industrial Maintenance Level 1
- PLC basics certificate (Allen-Bradley intro)

EXPERIENCE
- 3 years millwright helper: hydraulics troubleshooting, reading schematics on press lines
- Apprenticeship cohort volunteer mentor at local training center

EDUCATION
- Community college workforce board certificate, Industrial Maintenance
`;

const OKONKWO = `Sam Okonkwo
Maintenance Technician Candidate

Experience
- Warehouse equipment repair; basic electrical
- Familiar with hydraulic systems on forklifts
- Can read blueprints for rack installs

Education
- Trade school diploma
- Interested in Programmable Logic Controller courses (not yet certified)

Notes
- No OSHA-30 yet; scheduled for next month
- No NCCER card
`;

const CHEN = `Alex Chen
Retail associate seeking career change

Skills
- Customer service, inventory counting
- Microsoft Office

Education
- High school diploma

No trades certifications listed.
`;

export function defaultProfile(): RoleProfile {
  return {
    id: 'profile-ima',
    name: 'Industrial Maintenance Apprentice',
    jobDescription:
      'Apprenticeship cohort for industrial maintenance: OSHA-30, PLC basics, hydraulics, NCCER, blueprint/schematic reading. Journeyman pathway via union training center.',
    criteria: [
      { skill: 'OSHA-30', synonyms: ['OSHA30', 'Occupational Safety and Health Administration'], weight: 10 },
      { skill: 'PLC basics', synonyms: ['Programmable Logic Controller', 'PLC'], weight: 8 },
      { skill: 'hydraulics', synonyms: ['hydraulic systems'], weight: 6 },
      { skill: 'NCCER', synonyms: [], weight: 5 },
      { skill: 'blueprint reading', synonyms: ['reading schematics', 'schematics'], weight: 7 },
    ],
    sectionWeights: { certifications: 1.2, experience: 1.0, education: 0.8 },
    thresholds: { advance: 70, hold: 40 },
  };
}

export function createSeedWorkspace(): Workspace {
  const profile = defaultProfile();
  const now = new Date().toISOString();
  const resumes: ResumeAsset[] = [
    { id: 'res-rivera', filename: 'rivera.txt', rawText: RIVERA, importedAt: now, status: 'valid' },
    { id: 'res-okonkwo', filename: 'okonkwo.txt', rawText: OKONKWO, importedAt: now, status: 'valid' },
    { id: 'res-chen', filename: 'chen.txt', rawText: CHEN, importedAt: now, status: 'valid' },
  ];
  const results = resumes.map((r) => scoreResume(r, profile));
  const decisions = results.map((res) => ({
    resumeId: res.resumeId,
    bucket: suggestedBucket(res.totalScore, profile.thresholds),
    decidedBy: 'system-suggest',
    timestamp: now,
    confirmed: false,
    note: 'auto-bucketed; human must confirm',
  }));

  return {
    version: 1,
    profiles: [profile],
    activeProfileId: profile.id,
    resumes,
    results,
    decisions,
    audit: [
      {
        type: 'seed',
        payload: { profile: profile.name, resumes: resumes.length },
        timestamp: now,
      },
    ],
  };
}

:root {
  --bg: #f7f5f0;
  --ink: #1a1a1a;
  --muted: #4a4a4a;
  --line: #c8c2b4;
  --focus: #0b5fff;
  --advance: #1b6b3a;
  --hold: #8a5a00;
  --reject: #8b1e1e;
  --panel: #fffef9;
  font-family: "Segoe UI", "IBM Plex Sans", sans-serif;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  line-height: 1.45;
}

a.skip-link {
  position: absolute;
  left: -999px;
  top: 0;
  background: var(--focus);
  color: #fff;
  padding: 0.5rem 1rem;
  z-index: 100;
}
a.skip-link:focus { left: 0; }

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.app-header {
  border-bottom: 1px solid var(--line);
  padding: 0.75rem 1rem;
  display: flex;
  gap: 1rem;
  align-items: baseline;
  flex-wrap: wrap;
  background: var(--panel);
}

.app-header h1 {
  margin: 0;
  font-size: 1.25rem;
  letter-spacing: 0.02em;
}

.app-header .tag {
  color: var(--muted);
  font-size: 0.9rem;
}

nav.tabs {
  display: flex;
  gap: 0.25rem;
  padding: 0.5rem 1rem;
  border-bottom: 1px solid var(--line);
}

nav.tabs button {
  background: transparent;
  border: 1px solid transparent;
  padding: 0.4rem 0.75rem;
  cursor: pointer;
  color: var(--ink);
  font: inherit;
}

nav.tabs button[aria-selected="true"] {
  border-color: var(--line);
  background: var(--panel);
  font-weight: 600;
}

main {
  padding: 1rem;
  max-width: 1100px;
}

.layout-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

@media (max-width: 800px) {
  .layout-split { grid-template-columns: 1fr; }
}

.panel {
  background: var(--panel);
  border: 1px solid var(--line);
  padding: 0.75rem 1rem;
}

.queue-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.queue-list li {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 0.5rem;
  padding: 0.5rem 0.4rem;
  border-bottom: 1px solid var(--line);
  cursor: pointer;
}

.queue-list li[aria-selected="true"] {
  background: #e8eefc;
}

.bucket-advance { color: var(--advance); font-weight: 600; }
.bucket-hold { color: var(--hold); font-weight: 600; }
.bucket-reject { color: var(--reject); font-weight: 600; }

.evidence {
  white-space: pre-wrap;
  font-family: ui-monospace, Consolas, monospace;
  font-size: 0.85rem;
  border: 1px solid var(--line);
  padding: 0.75rem;
  background: #fff;
  max-height: 320px;
  overflow: auto;
}

.evidence mark {
  background: #ffe58a;
  color: inherit;
  padding: 0 1px;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin: 0.75rem 0;
}

button.action, label.action {
  font: inherit;
  padding: 0.35rem 0.7rem;
  border: 1px solid var(--line);
  background: #fff;
  cursor: pointer;
}

.live {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
}

.overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 50;
}

.overlay-card {
  background: var(--panel);
  border: 1px solid var(--line);
  padding: 1.25rem;
  max-width: 420px;
  width: 90%;
}

.overlay-card h2 { margin-top: 0; }
.overlay-card kbd {
  border: 1px solid var(--line);
  padding: 0 0.3rem;
  background: #fff;
  font-family: inherit;
}

.muted { color: var(--muted); }
.err { color: var(--reject); }
.ok { color: var(--advance); }

table.breakdown {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}
table.breakdown th, table.breakdown td {
  border-bottom: 1px solid var(--line);
  text-align: left;
  padding: 0.35rem 0.25rem;
}

input[type="number"], textarea, input[type="text"] {
  font: inherit;
  width: 100%;
  border: 1px solid var(--line);
  padding: 0.35rem;
  background: #fff;
}

