"""Pure-Python TF-IDF + cosine retrieval (no scikit-learn)."""
from __future__ import annotations

import math
import re
from collections import Counter
from typing import Iterable

TOKEN_RE = re.compile(r"[a-z0-9']+")


def tokenize(text: str) -> list[str]:
    return TOKEN_RE.findall((text or "").lower())


def tfidf_matrix(docs: list[str]) -> tuple[list[dict[str, float]], dict[str, float]]:
    tokenized = [tokenize(d) for d in docs]
    df: Counter[str] = Counter()
    for toks in tokenized:
        df.update(set(toks))
    n = len(docs) or 1
    idf = {t: math.log((1 + n) / (1 + c)) + 1.0 for t, c in df.items()}
    vectors: list[dict[str, float]] = []
    for toks in tokenized:
        tf = Counter(toks)
        length = len(toks) or 1
        vec = {t: (tf[t] / length) * idf[t] for t in tf}
        vectors.append(vec)
    return vectors, idf


def cosine(a: dict[str, float], b: dict[str, float]) -> float:
    if not a or not b:
        return 0.0
    keys = set(a) | set(b)
    dot = sum(a.get(k, 0.0) * b.get(k, 0.0) for k in keys)
    na = math.sqrt(sum(v * v for v in a.values()))
    nb = math.sqrt(sum(v * v for v in b.values()))
    if na == 0 or nb == 0:
        return 0.0
    return dot / (na * nb)


def rank(
    question: str,
    chunk_ids: list[str],
    texts: list[str],
    k: int = 4,
) -> list[tuple[str, str, float]]:
    if not texts:
        return []
    vectors, idf = tfidf_matrix(texts + [question])
    q_vec = vectors[-1]
    doc_vecs = vectors[:-1]
    scored: list[tuple[str, str, float]] = []
    for i, vec in enumerate(doc_vecs):
        scored.append((chunk_ids[i], texts[i], cosine(q_vec, vec)))
    scored.sort(key=lambda x: (-x[2], x[0]))
    return scored[:k]


def sentences(text: str) -> list[str]:
    parts = re.split(r"(?<=[.!?])\s+", text.strip())
    return [p.strip() for p in parts if p.strip()]


def extractive_answer(
    hits: list[tuple[str, str, float]],
    min_score: float,
) -> tuple[str, str, list[str], list[float]]:
    """Returns answer_html_safe_text, status, cited_ids, scores."""
    if not hits or hits[0][2] < min_score:
        return (
            "Abstaining — retrieval confidence is below the profile threshold. "
            "No extractive answer will be invented for this question.",
            "abstained",
            [],
            [h[2] for h in hits],
        )
    cited: list[str] = []
    scores: list[float] = []
    lines: list[str] = []
    for cid, text, score in hits:
        if score < min_score * 0.85:
            continue
        cited.append(cid)
        scores.append(score)
        # Prefer a sentence that overlaps the chunk well
        sents = sentences(text)
        pick = sents[0] if sents else text[:220]
        lines.append(f"{pick} [{cid}]")
    if not lines:
        return (
            "Abstaining — no chunk cleared the confidence floor.",
            "abstained",
            [],
            [h[2] for h in hits],
        )
    band = confidence_band(scores)
    body = " ".join(lines)
    return body, "answered", cited, scores


def confidence_band(scores: Iterable[float]) -> str:
    scores = list(scores)
    if not scores:
        return "Low"
    top = scores[0]
    margin = top - (scores[1] if len(scores) > 1 else 0.0)
    if top >= 0.22 and margin >= 0.04:
        return "High"
    if top >= 0.12:
        return "Medium"
    return "Low"


PROFILES = {
    "strict": {"k": 3, "min_score": 0.14},
    "balanced": {"k": 4, "min_score": 0.08},
    "exploratory": {"k": 5, "min_score": 0.04},
}

"""ClerkLens — cited Q&A over municipal meeting packets (Flask + CSV + pure TF-IDF)."""
from __future__ import annotations

import csv
import hashlib
import re
import uuid
from datetime import datetime, timezone
from html import escape
from pathlib import Path

from flask import Flask, abort, jsonify, redirect, render_template_string, request, url_for

from retrieval import PROFILES, confidence_band, extractive_answer, rank

APP_ROOT = Path(__file__).parent
DATA_DIR = APP_ROOT / "data"
FIX_DIR = APP_ROOT / "fixtures"
DATA_DIR.mkdir(exist_ok=True)

DOCS = DATA_DIR / "documents.csv"
CHUNKS = DATA_DIR / "chunks.csv"
QUERIES = DATA_DIR / "queries.csv"
ANSWERS = DATA_DIR / "answers.csv"
REQLOG = DATA_DIR / "request_log.csv"
MAX_BYTES = 2 * 1024 * 1024

HEADERS = {
    DOCS: ["doc_id", "filename", "doc_type", "meeting_date", "n_chars", "sha256", "ingested_at"],
    CHUNKS: ["chunk_id", "doc_id", "seq", "start", "end", "text", "token_count"],
    QUERIES: ["query_id", "asked_at", "question", "seed", "profile", "top_k"],
    ANSWERS: [
        "answer_id",
        "query_id",
        "status",
        "confidence_band",
        "answer_text",
        "cited_chunk_ids",
        "latency_ms",
    ],
    REQLOG: ["timestamp", "method", "path", "status_code", "duration_ms"],
}


def init_csvs() -> None:
    for path, header in HEADERS.items():
        if not path.exists():
            with path.open("w", newline="", encoding="utf-8") as f:
                csv.writer(f).writerow(header)


def now_iso() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def extract_text(path: Path) -> tuple[str, str | None]:
    """Return (text, error_message)."""
    ext = path.suffix.lower()
    if ext == ".txt":
        text = path.read_text(encoding="utf-8", errors="replace")
        if not text.strip():
            return "", "Empty text file rejected."
        return text, None
    if ext == ".pdf":
        # Lightweight text-layer stub: only accept tiny demo PDFs we don't ship;
        # scanned/empty PDFs get a distinct message. Prefer .txt fixtures.
        raw = path.read_bytes()
        if len(raw) < 20:
            return "", "Corrupt PDF rejected."
        # Heuristic: if almost no ASCII letters, treat as scanned / no text layer
        ascii_letters = sum(1 for b in raw if 65 <= b <= 90 or 97 <= b <= 122)
        if ascii_letters < 40:
            return "", "Scanned PDF with no extractable text layer — convert to .txt first."
        # Extract crude ASCII strings as a demo "text layer"
        text = " ".join(re.findall(rb"[A-Za-z0-9 ,.\-]{4,}", raw).decode("ascii", "ignore") for _ in [0])
        # fallback decode attempt
        try:
            text = re.sub(rb"[^\x20-\x7e\n\r\t]+", b" ", raw).decode("ascii", "ignore")
        except Exception:
            text = ""
        text = re.sub(r"\s+", " ", text).strip()
        if len(text) < 40:
            return "", "Scanned PDF with no extractable text layer — convert to .txt first."
        return text, None
    return "", f"Unsupported file type ({ext}). Only .txt and .pdf."


def chunk_text(text: str, doc_id: str, size: int = 450, overlap: int = 80) -> list[dict]:
    chunks = []
    i = 0
    seq = 0
    n = len(text)
    while i < n:
        end = min(i + size, n)
        # Prefer paragraph boundary near end
        window = text[i:end]
        if end < n:
            cut = window.rfind("\n\n")
            if cut > size // 3:
                end = i + cut
                window = text[i:end]
        cid = f"{doc_id}-c{seq:04d}"
        chunks.append(
            {
                "chunk_id": cid,
                "doc_id": doc_id,
                "seq": seq,
                "start": i,
                "end": end,
                "text": window.strip(),
                "token_count": len(window.split()),
            }
        )
        if end >= n:
            break
        i = max(end - overlap, i + 1)
        seq += 1
    return [c for c in chunks if c["text"]]


def read_rows(path: Path) -> list[dict]:
    if not path.exists():
        return []
    with path.open("r", newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def append_row(path: Path, row: list) -> None:
    with path.open("a", newline="", encoding="utf-8") as f:
        csv.writer(f).writerow(row)


def infer_doc_type(name: str) -> str:
    n = name.lower()
    if "agenda" in n:
        return "agenda"
    if "minute" in n:
        return "minutes"
    if "ordinance" in n:
        return "ordinance"
    return "minutes"


def ingest_bytes(filename: str, data: bytes) -> tuple[dict | None, str]:
    """Ingest file bytes → (doc_meta, message). Raises via return error string."""
    ext = Path(filename).suffix.lower()
    if ext not in {".txt", ".pdf"}:
        return None, f"Unsupported type for “{filename}” (only .txt / .pdf)."
    if len(data) > MAX_BYTES:
        return None, f"File too large ({len(data)} bytes). Max 2 MB."
    if len(data) == 0:
        return None, f"Empty file rejected: “{filename}”."

    digest = sha256_bytes(data)
    for row in read_rows(DOCS):
        if row.get("sha256") == digest:
            return None, f"Duplicate packet skipped (already ingested as {row.get('doc_id')})."

    tmp = DATA_DIR / f"_tmp_{uuid.uuid4().hex}{ext}"
    tmp.write_bytes(data)
    try:
        text, err = extract_text(tmp)
        if err:
            return None, err
        doc_id = digest[:12]
        meta = {
            "doc_id": doc_id,
            "filename": Path(filename).name,
            "doc_type": infer_doc_type(filename),
            "meeting_date": "2024-03-12" if "2024-03-12" in filename else "",
            "n_chars": len(text),
            "sha256": digest,
            "ingested_at": now_iso(),
        }
        append_row(
            DOCS,
            [
                meta["doc_id"],
                meta["filename"],
                meta["doc_type"],
                meta["meeting_date"],
                meta["n_chars"],
                meta["sha256"],
                meta["ingested_at"],
            ],
        )
        for c in chunk_text(text, doc_id):
            append_row(
                CHUNKS,
                [c["chunk_id"], c["doc_id"], c["seq"], c["start"], c["end"], c["text"], c["token_count"]],
            )
        n_chunks = sum(1 for r in read_rows(CHUNKS) if r["doc_id"] == doc_id)
        return meta, f"Ingested {meta['filename']} as {doc_id} ({meta['doc_type']}) · {n_chunks} chunks."
    finally:
        if tmp.exists():
            tmp.unlink(missing_ok=True)


def load_sample_corpus() -> list[str]:
    msgs = []
    for path in sorted(FIX_DIR.glob("*.txt")):
        _, msg = ingest_bytes(path.name, path.read_bytes())
        msgs.append(msg)
    return msgs


init_csvs()
app = Flask(__name__)

