#!/usr/bin/env node
/**
 * Auto-continue Stop hook for gpt-oss datagen sessions.
 * Must be .cjs — package.json may have "type": "module".
 *
 * IMPORTANT: Do NOT use decision:"block" — Chakra/Claude UI labels that
 * "Stop hook error". Use hookSpecificOutput.additionalContext instead
 * (official "non-error feedback that continues the conversation").
 */
const fs = require("fs");
const path = require("path");

const MAX_AUTO = Number(process.env.DATAGEN_CONTINUE_MAX || 120);
const DONE_RE = /\bDONE\b[\s:_-]*task[_\s]?\d+/i;
const MARATHON_DONE_RE = /\bDONE\b[\s:_-]*task[_\s]?10\b/i;

function findChakraRoot(start) {
  let dir = path.resolve(start || process.cwd());
  for (let i = 0; i < 12; i++) {
    const hook = path.join(dir, ".claude", "hooks", "datagen-continue.cjs");
    const settings = path.join(dir, ".claude", "settings.json");
    if (fs.existsSync(hook) || fs.existsSync(settings)) return dir;
    const parent = path.dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return path.resolve(__dirname, "..", "..");
}

const ROOT = findChakraRoot(process.cwd());
const STATE = path.join(ROOT, ".claude", "datagen-continue.state.json");

function readStdin() {
  return new Promise((resolve) => {
    let data = "";
    process.stdin.setEncoding("utf8");
    process.stdin.on("data", (c) => (data += c));
    process.stdin.on("end", () => resolve(data));
  });
}

function loadState() {
  try {
    return JSON.parse(fs.readFileSync(STATE, "utf8"));
  } catch {
    return { count: 0 };
  }
}

function saveState(s) {
  fs.mkdirSync(path.dirname(STATE), { recursive: true });
  fs.writeFileSync(STATE, JSON.stringify(s));
}

function clearState() {
  try {
    fs.unlinkSync(STATE);
  } catch {
    /* ok */
  }
}

function lastAssistantText(transcriptPath) {
  if (!transcriptPath || !fs.existsSync(transcriptPath)) return "";
  const lines = fs.readFileSync(transcriptPath, "utf8").split(/\r?\n/).filter(Boolean);
  let text = "";
  for (let i = lines.length - 1; i >= 0; i--) {
    try {
      const row = JSON.parse(lines[i]);
      const role = row.role || row.message?.role;
      if (role !== "assistant") continue;
      const content = row.message?.content || row.content;
      if (typeof content === "string") {
        text = content;
        break;
      }
      if (Array.isArray(content)) {
        const parts = content.filter((c) => c?.type === "text").map((c) => c.text || "");
        if (parts.length) {
          text = parts.join("\n");
          break;
        }
      }
    } catch {
      /* skip */
    }
  }
  return text;
}

function allowStop() {
  clearState();
  // Empty allow — no JSON decision block, no error banner
  process.exit(0);
}

async function main() {
  const raw = await readStdin();
  let input = {};
  try {
    input = JSON.parse(raw.replace(/^\uFEFF/, "").trim() || "{}");
  } catch {
    process.exit(0);
  }

  const status = input.status || input.stop_reason || "completed";
  if (status === "error" || status === "aborted") process.exit(0);

  const last = lastAssistantText(input.transcript_path);
  // Only fully release on explicit DONE task_N (marathon step complete)
  if (DONE_RE.test(last)) {
    // Reset continue counter between tasks so the next task gets a fresh budget
    clearState();
    // If only mid-marathon DONE (not task 10), still continue to next task
    if (!MARATHON_DONE_RE.test(last) && !/\bDONE\b[\s:_-]*task[_\s]?10\b/i.test(last)) {
      const state = { count: 1 };
      saveState(state);
      process.stdout.write(
        JSON.stringify({
          suppressOutput: true,
          hookSpecificOutput: {
            hookEventName: "Stop",
            additionalContext:
              "Task DONE recorded. Immediately open the next task platform_prompt.md only (do not load the full forged paste file). Implement with tools until that task is demoable, then print DONE task_N. Do not ask the user. Do not plan-only. Do not leave background shells hanging — finish or kill them before the next stop.",
          },
        })
      );
      process.exit(0);
    }
    allowStop();
  }

  const state = loadState();
  state.count = (state.count || 0) + 1;
  if (state.count > MAX_AUTO) {
    clearState();
    process.exit(0);
  }
  saveState(state);

  // Non-error continuation (NOT decision:block — that shows "Stop hook error")
  process.stdout.write(
    JSON.stringify({
      suppressOutput: true,
      hookSpecificOutput: {
        hookEventName: "Stop",
        additionalContext: [
          `Datagen resume ${state.count}/${MAX_AUTO}.`,
          "You stopped before printing DONE task_N.",
          "Immediately call tools and keep implementing the current task until it is runnable and acceptance criteria pass.",
          "Then print: DONE task_N: <title> — path + how to run",
          "Then open the next single platform_prompt.md and continue.",
          "Forbidden: asking the user, plan-only turns, loading the whole CHAKRA_PASTE file,",
          "claiming DONE with non-working stub HTML, leaving npm/servers hung in background.",
          "Ship a real interactive demo matching the PRD (forms/API actions that work in the browser).",
        ].join(" "),
      },
    })
  );
  process.exit(0);
}

main().catch(() => process.exit(0));

