:root {
  --bg: #e7eef5;
  --ink: #132033;
  --panel: #f7fafc;
  --line: #b7c4d4;
  --accent: #0b5f8a;
  --ok: #1b6b3a;
  --warn: #8a5a00;
  --bad: #8b1e1e;
  font-family: "IBM Plex Sans", "Segoe UI", sans-serif;
}
* { box-sizing: border-box; }
body { margin: 0; background: linear-gradient(180deg, #d5e3f0, var(--bg)); color: var(--ink); min-height: 100vh; }
.top {
  display: flex; justify-content: space-between; gap: 1rem; align-items: flex-start;
  padding: 1.1rem 1.4rem; background: #0f2740; color: #eef5fb;
  border-bottom: 4px solid #2aa0c8;
}
.top h1 { margin: 0; font-size: 1.45rem; }
.top p { margin: 0.35rem 0 0; color: #b9c9da; max-width: 40rem; font-size: 0.95rem; }
.status {
  background: #173552; border: 1px solid #3a5d7f; padding: 0.4rem 0.7rem; font-size: 0.85rem;
}
.layout {
  display: grid; grid-template-columns: 1.1fr 1fr; gap: 1rem; padding: 1rem 1.25rem 2rem; max-width: 1180px; margin: 0 auto;
}
.panel {
  background: var(--panel); border: 1px solid var(--line); padding: 0.9rem 1rem;
  box-shadow: 0 1px 0 rgba(19,32,51,0.05);
}
.panel.wide { grid-column: 1 / -1; }
h2 { margin: 0 0 0.7rem; font-size: 1.05rem; }
label { display: block; margin: 0.45rem 0; font-size: 0.9rem; }
input, select, textarea, button {
  font: inherit; width: 100%; margin-top: 0.25rem; padding: 0.4rem 0.5rem; border: 1px solid var(--line); background: #fff;
}
button { width: auto; background: var(--accent); color: #fff; border: 0; cursor: pointer; padding: 0.45rem 0.8rem; }
button.secondary { background: #fff; color: var(--ink); border: 1px solid var(--line); }
.row { display: flex; flex-wrap: wrap; gap: 0.5rem; margin-top: 0.75rem; }
.tabs { display: flex; flex-wrap: wrap; gap: 0.35rem; margin-bottom: 0.7rem; }
.tabs button { background: #fff; color: var(--ink); border: 1px solid var(--line); }
.tabs button.active { background: #d7ebf5; border-color: var(--accent); font-weight: 600; }
.list { display: grid; gap: 0.5rem; max-height: 360px; overflow: auto; }
.card {
  border: 1px solid var(--line); background: #fff; padding: 0.55rem 0.65rem; font-size: 0.9rem;
}
.muted { color: #536579; }
.hidden { display: none; }
.result { margin-top: 0.85rem; border: 1px solid var(--line); background: #fff; padding: 0.7rem; }
.chip {
  display: inline-block; margin: 0.15rem 0.2rem 0 0; padding: 0.15rem 0.45rem;
  background: #e4f2e9; border: 1px solid #9fcec0; font-size: 0.8rem;
}
.code { background: #0f2740; color: #d7e8f7; padding: 0.75rem; overflow: auto; font-size: 0.85rem; }
@media (max-width: 900px) { .layout { grid-template-columns: 1fr; } }

const QUEUES = ['safety', 'fare-billing', 'fleet-damage', 'accessibility', 'general', 'review'];
let activeQueue = 'safety';

const healthEl = document.getElementById('health');
const tabsEl = document.getElementById('queue-tabs');
const listEl = document.getElementById('queue-list');
const statsEl = document.getElementById('stats');
const resultEl = document.getElementById('result');

QUEUES.forEach((q) => {
  const b = document.createElement('button');
  b.type = 'button';
  b.textContent = q;
  b.dataset.q = q;
  if (q === activeQueue) b.classList.add('active');
  b.addEventListener('click', () => {
    activeQueue = q;
    [...tabsEl.children].forEach((c) => c.classList.toggle('active', c.dataset.q === q));
    loadQueue();
  });
  tabsEl.appendChild(b);
});

async function api(path, opts) {
  const res = await fetch(path, {
    headers: { 'Content-Type': 'application/json', ...(opts?.headers || {}) },
    ...opts,
  });
  const text = await res.text();
  let data;
  try { data = text ? JSON.parse(text) : null; } catch { data = { raw: text }; }
  if (!res.ok) throw Object.assign(new Error(data?.error?.message || res.statusText), { status: res.status, data });
  return data;
}

async function refreshHealth() {
  try {
    const h = await api('/health');
    healthEl.textContent = `API ${h.status}`;
    healthEl.style.color = '#8dffb0';
  } catch {
    healthEl.textContent = 'API down';
    healthEl.style.color = '#ffb4b4';
  }
}

async function loadQueue() {
  listEl.textContent = 'Loading…';
  try {
    const rows = await api(`/queues/${encodeURIComponent(activeQueue)}/tickets`);
    if (!rows.length) {
      listEl.innerHTML = `<div class="muted">No tickets in <strong>${activeQueue}</strong>.</div>`;
      return;
    }
    listEl.innerHTML = rows.map((t) => `
      <article class="card">
        <div><strong>${escapeHtml(t.subject || '(no subject)')}</strong> · ${escapeHtml(t.status || '')}</div>
        <div class="muted">${escapeHtml(t.channel || '')} · ${escapeHtml(t.author_handle || '')} · ${escapeHtml(t.created_at || '')}</div>
        <div>${escapeHtml(t.body || '')}</div>
      </article>`).join('');
  } catch (e) {
    listEl.innerHTML = `<div class="muted">Queue load failed: ${escapeHtml(e.message)}</div>`;
  }
}

async function loadStats() {
  try {
    const s = await api('/stats');
    statsEl.textContent = JSON.stringify(s, null, 2);
  } catch (e) {
    statsEl.textContent = `stats failed: ${e.message}`;
  }
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

document.getElementById('ticket-form').addEventListener('submit', async (ev) => {
  ev.preventDefault();
  const fd = new FormData(ev.target);
  const payload = Object.fromEntries(fd.entries());
  resultEl.classList.remove('hidden');
  resultEl.textContent = 'Classifying…';
  try {
    const out = await api('/tickets', { method: 'POST', body: JSON.stringify(payload) });
    const evd = (out.evidence || []).map((e) => `<span class="chip">${escapeHtml(e.type)}:${escapeHtml(e.term)}</span>`).join('');
    resultEl.innerHTML = `
      <div><strong>Ticket</strong> ${escapeHtml(out.id || out.ticket_id || '')} · status ${escapeHtml(out.status || '')}</div>
      <div>sentiment <strong>${escapeHtml(out.sentiment)}</strong> · urgency <strong>${escapeHtml(out.urgency)}</strong> · category <strong>${escapeHtml(out.category)}</strong></div>
      <div>confidence ${(Number(out.confidence) || 0).toFixed(3)}${out.suggested_queue ? ` · suggested ${escapeHtml(out.suggested_queue)}` : ''}</div>
      <div style="margin-top:0.4rem">${evd || '<span class="muted">no evidence terms</span>'}</div>`;
    activeQueue = out.status === 'review' ? 'review' : (out.category || activeQueue);
    [...tabsEl.children].forEach((c) => c.classList.toggle('active', c.dataset.q === activeQueue));
    await Promise.all([loadQueue(), loadStats()]);
  } catch (e) {
    resultEl.innerHTML = `<div style="color:var(--bad)">Error ${e.status || ''}: ${escapeHtml(e.message)}</div>`;
  }
});

